// Validate subject property input before sending to ValueProof backend
const body = items[0].json.body || items[0].json;

if (!body.location || !body.location.city || !body.location.locality) {
  throw new Error('Validation Error: Missing required location (city, locality).');
}
if (!body.area_sqft || body.area_sqft <= 0) {
  throw new Error('Validation Error: area_sqft must be strictly positive.');
}
if (!body.property_type) {
  throw new Error('Validation Error: Missing property_type.');
}

return [{ json: { property: body, asking_price: body.asking_price || null, include_ai_explanation: false } }];

// Merge structured valuation with workflow orchestration output
const valuation = items[0].json;
const aiSummary = items[0].json.text || valuation.ai_explanation || '';

return [{
  json: {
    status: 'success',
    orchestrator: 'n8n',
    estimated_value: valuation.estimated_value,
    valuation_range: valuation.valuation_range,
    representative_price_per_sqft: valuation.representative_price_per_sqft,
    price_breakdown: valuation.price_breakdown,
    evidence_passport: valuation.evidence_passport,
    location_intelligence: valuation.location_intelligence,
    negotiation_lens: valuation.negotiation_lens,
    ai_explanation: aiSummary
  }
}];
